<?php require_once "../config/auth.php";require_admin();$p=db();if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$id=(int)$_POST["id"];if($_POST["action"]==="block"||$_POST["action"]==="active")$p->prepare("UPDATE users SET status=? WHERE id=?")->execute([$_POST["action"],$id]);if($_POST["action"]==="add")$p->prepare("UPDATE users SET balance=balance+? WHERE id=?")->execute([(float)$_POST["amount"],$id]);}$rows=$p->query("SELECT id,username,email,balance,role,status FROM users ORDER BY id DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../public/style.css"></head><body><main><h1>Users</h1><div class="table"><table><tr><th>ID</th><th>User</th><th>Email</th><th>Balance</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=$r["id"]?></td><td><?=e($r["username"])?></td><td><?=e($r["email"])?></td><td>৳<?=$r["balance"]?></td><td><?=$r["status"]?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r["id"]?>"><?php if($r["status"]==="active"):?><button name="action" value="block">Block</button><?php else:?><button name="action" value="active">Activate</button><?php endif;?><input name="amount" type="number" step=".01" placeholder="+balance" style="width:100px"><button name="action" value="add">Add</button></form></td></tr><?php endforeach;?></table></div></main></body></html>